            pen.line([(3, 15), (21, 15)])
            pen.line([(11, 20), (21, 20)])
        case "text.append":
            pen.line([(3, 5), (21, 5)])
            pen.line([(3, 10), (21, 10)])
            pen.line([(3, 15), (12, 15)])
            pen.line([(17, 13), (17, 21)])
